function show(s) {
  const toks = syn.tokenize(s);
  const t0 = Date.now();
  const r = syn.translate(toks);
  const ms = Date.now() - t0;
  if (r) console.log('○ ' + s + '\n   → ' + r.ja + '   [' + r.sp + '] ' + r.names.join(',') + (r.unknown.length ? ' unk:' + r.unknown.join(',') : '') + (ms > 80 ? ' (' + ms + 'ms)' : ''));
  else { const c = syn.chunks(toks); console.log('× ' + s + '\n   ／ ' + c.ja + (ms > 80 ? ' (' + ms + 'ms)' : '')); }
  return !!r;
}
const arg = process.argv[2] || 'core';
let list;
if (arg === 'core') list = CORE; else if (arg === 'more') list = MORE; else if (arg === 'all') list = CORE.concat(MORE);
else if (arg === 'passages') {
  list = [];
  JK.passageList.forEach((p) => p.paras.forEach((para) => para.forEach((st) => list.push(JK.passage.plain(st.en)))));
  list = list.slice(0, Number(process.argv[3] || 60));
} else list = process.argv.slice(2);
let ok = 0;
list.forEach((s) => { if (show(s)) ok++; });
console.log('\nparsed ' + ok + ' / ' + list.length);
